import {webkit,devices} from 'playwright';
const browser=await webkit.launch({headless:true});
const page=await browser.newPage({...devices['iPhone 13'],userAgent:devices['iPhone 13'].userAgent+' KAKAOTALK'});
page.setDefaultTimeout(18000);
const actionBodies=[],legacyAssetRequests=[];
const member=(id,name,gender,cls,role='member',year=1990)=>({id,name,gender,cls,role,year,age:String(Math.floor((2026-year)/10)*10),type:'member',state:'out',totalGames:0,joinedAt:Date.now()-60000});
const membersA=[member('mgr','배솜다리','여','C','manager',1990),...Array.from({length:17},(_,i)=>member('m'+(i+1),'회원'+(i+1),(i%2?'여':'남'),['A','B','C','D','E'][i%5],'member',1980+i))];
const membersB=[member('mgrb','배솜다리','여','C','manager',1990),member('b1','비회원1','남','B'),member('b2','비회원2','여','D')];
const state=gid=>({data:{dayKey:'2026-08-28',courtCount:4,courtNames:['1코트','2코트','3코트','4코트'],members:gid==='grp_b'?membersB:membersA,queue:[],pendingGames:[],games:[],history:[],pairCounts:{},attendancePolls:[]},user:{role:'manager',displayName:'배솜다리',memberId:gid==='grp_b'?'mgrb':'mgr',globalAdmin:false,groupId:gid,groupName:gid==='grp_b'?'B모임':'테스트모임'},group:{groupId:gid,name:gid==='grp_b'?'B모임':'테스트모임'},groups:[{groupId:'grp_a',name:'테스트모임'},{groupId:'grp_b',name:'B모임'}]});
await page.addInitScript(()=>{localStorage.setItem('kokmatch_token','qa-token-a');localStorage.setItem('kokmatch_group_id','grp_a');window.__qaTouchEvents=[];document.addEventListener('touchstart',e=>window.__qaTouchEvents.push(['start',e.target?.tagName,e.target?.className,e.target?.textContent?.trim()?.slice(0,30)]),true);document.addEventListener('touchend',e=>window.__qaTouchEvents.push(['end',e.target?.tagName,e.target?.className,e.target?.textContent?.trim()?.slice(0,30)]),true);document.addEventListener('click',e=>window.__qaTouchEvents.push(['click',e.target?.tagName,e.target?.className,e.target?.textContent?.trim()?.slice(0,30)]),true)});
page.on('request',req=>{try{const p=new URL(req.url()).pathname;if(/^\/app-v/i.test(p)&&p!=='/app-v6.0.js'&&p!=='/app-v6.0.css')legacyAssetRequests.push(p)}catch{}});
await page.route('**/latest-version.json*',r=>r.fulfill({status:200,contentType:'application/json',body:JSON.stringify({version:60,label:'6.0',semanticVersion:'6.0'})}));
await page.route('https://wjelumpbjklfrdjxbesj.supabase.co/functions/v1/**',async route=>{const req=route.request(),u=new URL(req.url()),path=u.pathname;let body={};try{body=req.postData()?JSON.parse(req.postData()):{}}catch{}let out={};if(path.endsWith('/kokmatch-multi-api')){const api=u.searchParams.get('api');if(api==='state')out=state(u.searchParams.get('groupId')||'grp_a');else if(api==='action'){actionBodies.push(body);out={data:state(body.groupId||'grp_a').data}}}else if(path.endsWith('/kokmatch-state-v46')){const g=u.searchParams.get('groupId')||'grp_a';out={...state(g),memberCount:state(g).data.members.length}}else if(path.endsWith('/kokmatch-auth-v38')){if(body.action==='my_memberships')out={memberships:[{groupId:'grp_a',groupName:'테스트모임',memberId:'mgr',role:'manager',roleLabel:'모임관리자'},{groupId:'grp_b',groupName:'B모임',memberId:'mgrb',role:'manager',roleLabel:'모임관리자'}]};else if(body.action==='switch_group')out={success:true,token:'qa-token-'+body.groupId,groupId:body.groupId,groupName:body.groupId==='grp_b'?'B모임':'테스트모임',memberId:body.groupId==='grp_b'?'mgrb':'mgr',role:'manager',roleLabel:'모임관리자'}}else if(path.endsWith('/kokmatch-profile-v53'))out=u.searchParams.get('full')==='1'?{image:'',fullImage:''}:{profiles:{}};else if(path.endsWith('/kokmatch-updater'))out={version:60,label:'6.0',autoUpdate:false};else if(path.endsWith('/kokmatch-v66-api'))out={data:state(body.groupId||'grp_a').data};else out={data:state(body.groupId||'grp_a').data};await route.fulfill({status:200,contentType:'application/json',body:JSON.stringify(out)})});
const errors=[];page.on('pageerror',e=>errors.push(e.message));
async function tapFresh(factory,label){let last;for(let i=0;i<12;i++){try{const loc=factory().first();await loc.waitFor({state:'visible',timeout:2500});await loc.scrollIntoViewIfNeeded();await page.waitForTimeout(260);const current=factory().first();const b=await current.boundingBox();if(!b)throw new Error('no bounding box');const hit=await page.evaluate(({x,y})=>document.elementsFromPoint(x,y).slice(0,8).map(el=>({tag:el.tagName,id:el.id,cls:el.className,text:(el.textContent||'').trim().slice(0,40)})),{x:b.x+b.width/2,y:b.y+b.height/2});console.log('HIT '+label,JSON.stringify(hit));await page.touchscreen.tap(b.x+b.width/2,b.y+b.height/2);console.log('EVENTS '+label,JSON.stringify(await page.evaluate(()=>window.__qaTouchEvents.splice(0))));console.log('CORE '+label,await page.evaluate(()=>window.__kokmatchInteractionCore||''));return}catch(e){last=e;await page.waitForTimeout(140)}}throw new Error('tap failed '+label+': '+String(last?.message||last))}
await page.goto('http://127.0.0.1:4173/?qa=v6standalone',{waitUntil:'domcontentloaded'});
await page.waitForFunction(()=>window.__kokmatchStandalone==='6.0'&&window.__kokmatchInteractionCore==='6.0'&&window.__kokmatchRosterCanonical==='22.3');
await page.waitForFunction(()=>document.querySelectorAll('#members .memberCard').length===10);
await page.evaluate(()=>{window.openEditMember=()=>{throw new Error('legacy edit must not run')};window.setOther=()=>{throw new Error('legacy setOther must not run')};window.openGroupSwitch23=()=>{throw new Error('legacy group23 must not run')};window.openGroupSwitch=()=>{throw new Error('legacy group must not run')}});
await page.waitForTimeout(600);
await tapFresh(()=>page.locator('#members .memberCard[data-member-id22="m1"] .btn.enter'),'attendance-first');
await page.waitForTimeout(600);if(!actionBodies.some(x=>x.action==='set_member_attendance'&&x.memberId==='m1'&&x.mode==='waiting'))throw new Error('direct attendance missing '+JSON.stringify(actionBodies));console.log('PASS V6 attendance');
await tapFresh(()=>page.locator('#members .memberCard[data-member-id22="m1"] button').filter({hasText:'수정'}),'edit');
await page.waitForSelector('#modal.on #fmName');if(await page.locator('#fmName').inputValue()!=='회원1')throw new Error('wrong edit member');console.log('PASS V6 edit');await page.evaluate(()=>closeModal());await page.waitForTimeout(350);
await tapFresh(()=>page.locator('#members .memberPager46 button').filter({hasText:'다음'}),'pager next');await page.waitForFunction(()=>window.__kokmatchMemberPage46===2);console.log('PASS V6 pager');
await tapFresh(()=>page.locator('#members .memberPager46 button').filter({hasText:'이전'}),'pager prev');await page.waitForFunction(()=>window.__kokmatchMemberPage46===1);
await tapFresh(()=>page.locator('#groupBtn'),'group open');await page.waitForSelector('#groupChoiceV6');console.log('PASS V6 group open');
await tapFresh(()=>page.locator('#groupChoiceV6 button').filter({hasText:'B모임'}),'group B');await page.waitForFunction(()=>window.currentGroupId==='grp_b'&&document.querySelector('#groupBtn')?.textContent.includes('B모임'));console.log('PASS V6 group switch');
if(legacyAssetRequests.length)throw new Error('legacy app assets requested '+JSON.stringify(legacyAssetRequests));
if(errors.length)throw new Error('page errors '+JSON.stringify(errors));console.log('PASS V6 STANDALONE IOS TOUCH ALL');await browser.close();